import itertools

def count_weak_quartets(n, edges):
    count = 0
    for quartet in itertools.combinations(range(n), 4):
        edge_count = 0
        for i in range(4):
            for j in range(i + 1, 4):
                if (quartet[i], quartet[j]) in edges or (quartet[j], quartet[i]) in edges:
                    edge_count += 1
        if edge_count == 1:
            count += 1
    return count

def get_max_weak_quartets(n):
    max_w = 0
    # We can't iterate through all graphs, but we can try some structures
    # 1. Matching
    m = n // 2
    edges = set()
    for i in range(m):
        edges.add((2*i, 2*i+1))
    max_w = max(max_w, count_weak_quartets(n, edges))

    # 2. Star
    for m in range(1, n):
        edges = set()
        for i in range(1, m+1):
            edges.add((0, i))
        max_w = max(max_w, count_weak_quartets(n, edges))

    # 3. Complete graph K_p
    for p in range(2, n+1):
        edges = set()
        for i in range(p):
            for j in range(i+1, p):
                edges.add((i, j))
        max_w = max(max_w, count_weak_quartets(n, edges))

    # 4. Union of K_p's
    for p in range(2, n+1):
        if n % p == 0:
            edges = set()
            for i in range(n // p):
                for j in range(p):
                    for k in range(j+1, p):
                        edges.add((i*p + j, i*p + k))
            max_w = max(max_w, count_weak_quartets(n, edges))

    # 5. Random graphs
    for _ in range(100):
        import random
        m = random.randint(1, n*(n-1)//2)
        edges = set()
        all_edges = list(itertools.combinations(range(n), 2))
        edges = set(random.sample(all_edges, m))
        max_w = max(max_w, count_weak_quartets(n, edges))

    return max_w

for n in range(4, 11):
    print(f"n={n}, max_w={get_max_weak_quartets(n)}")

def count_weak_quartets(edges, n):
    count = 0
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                for l in range(k + 1, n):
                    # Vertices are i, j, k, l
                    # Check edges among them
                    edges_count = 0
                    # Check all 6 pairs
                    pairs = [(i, j), (i, k), (i, l), (j, k), (j, l), (k, l)]
                    for p1, p2 in pairs:
                        if (p1, p2) in edges or (p2, p1) in edges:
                            edges_count += 1
                    if edges_count == 1:
                        count += 1
    return count

